/** SpongeCheck Phase 4: deterministic rain scenario and transparent inspection priorities on existing Phase 3. */
type Role = 'Inspector' | 'Manager' | 'Reviewer' | 'Guest';
type Theme = 'light' | 'dark';
type ViewMode = 'map' | 'list';
type PlaceType = 'Outlet' | 'Wetland' | 'Swale' | 'Pond';
type PlaceStatus = 'Needs checking' | 'Review needed' | 'On schedule';
type Notice = { id: string; title: string; desc: string; date: string; read: boolean; caseId?: string };
type Place = { id: string; name: string; type: PlaceType; zone: string; status: PlaceStatus; description: string; image: string; photo: string; position: {x: number; y: number} };
type Condition = 'none' | 'visible' | 'unsure';
type VegetationCondition = 'normal' | 'dense' | 'unsure';
type AnalysisMode = 'simulated_labels' | 'manual_only';
type Observations = { debris: Condition; sediment: Condition; vegetation: VegetationCondition; inspectorConfirmed: boolean; analysisMode: AnalysisMode };
type CaseEvent = { id: string; atUtc: string; type: string; actor: Role; description: string };
type TelegramCase = { id:string;placeId:string;placeName:string;note:string;photoData:string;createdAt:string;status:string;source:'telegram';observations:Observations;events:CaseEvent[] };
type TelegramStatus = {configured:boolean;connected:boolean;botUsername:string;message:string;lastInboundAt?:string};
type Report = {workflow?:WorkRecord;  id: string; placeId: string; note: string; photoName: string; photoData?: string; createdAt: string; status: string; observations?: Observations; photoSource?: 'uploaded' | 'sample'; events?: CaseEvent[]; schemaVersion?: number };
type State = {
  route: string; role: Role; theme: Theme; showMenu: boolean; showIntro: boolean;
  showHelp: boolean; showSource: boolean; toast: string; filter: string; search: string; viewMode: ViewMode;
  selectedPlace: string; notices: Notice[]; reports: Report[]; reportPlace: string;
  reportNote: string; reportPhotoName: string; reportPhotoData: string; reportBusy: boolean;
  reportStep: 1 | 2 | 3; reportMode: AnalysisMode; reportPhotoSource: 'uploaded'|'sample'|null;
  observations: Omit<Observations, 'inspectorConfirmed'|'analysisMode'>; observationConfirmed: boolean;
  reportError: string; reportPhotoError: string;
  showReset: boolean; reduceMotion: boolean; demoTour: number; showFeatured: boolean;
  scenario:RainScenario; compareRain:boolean; decisionFilter:'all'|'attention'; proposedAction:ProposedAction;
  workAction:ProposedAction; workReason:string; workCrew:string; workNote:string; workAfterData:string; workAfterName:string; workPhotoBusy:boolean; workError:string; workSlider:number;
  telegramApiBase:string; telegramDashboardKey:string; telegramBusy:boolean;telegramError:string; telegramStatus:TelegramStatus|null;telegramCases:TelegramCase[];telegramSyncedAt:string;telegramMockVisible:boolean; exportBusy:boolean; exportError:string; exportSuccess:string; insightsPeriod:'all'|'week'|'month';
};

